alias.typescript:
export interface UserAlias extends AutomationMeta {
    pattern: string;
    /**
     * The commands to send, `;` or newline separated. When `macros` is set
     * this is only a mirror of its command actions, kept so writers and readers
     * that predate actions (the assistant, imports, an older synced client)
     * still see a working alias.
     */
    command: string;
    /** Actions run in order. Absent means one command action with `command`. */
    macros?: UserMacro[];
    /** Per character: replaces every command action of the alias. */
    overrides?: Record<string, string>;
}

trigger.typescript:
export type TriggerType = 'pattern' | 'event';

export interface UserTrigger extends AutomationMeta {
    type?: TriggerType;  // defaults to 'pattern' for backwards compatibility
    pattern?: string;    // for pattern triggers
    event?: string;      // for event triggers (e.g., 'kill', 'combatState')
    flags?: string;      // for pattern triggers only
    gmcpMsgType?: string; // limit pattern trigger to specific GMCP message type
    /** Event triggers only: every condition must hold for the macros to run. */
    conditions?: TriggerCondition[];
    macros: UserMacro[];
}

export type ConditionOperator = 'eq' | 'neq' | 'like' | 'notLike' | 'gt' | 'gte' | 'lt' | 'lte';

export interface TriggerCondition {
    arg: string;
    op: ConditionOperator;
    value: string;
}

export interface EventArg {
    name: string;
    label: string;
    /** Decides which condition operators the editor offers for this arg. */
    type?: EventArgType;
}

export interface SupportedEvent {
    id: string;
    label: string;
    category: string;
    /**
     * When the event actually fires, shown under the picker in the editor.
     *
     * Worth writing wherever the label alone leaves it ambiguous — several of
     * these fire on a delay, or only when some other setting is enabled, and a
     * label has no room to say so. Omitted where the label is self-evident.
     */
    description?: string;
    /**
     * Values this event's payload carries. Macro text fields may reference them
     * as `{name}`; see `interpolateEventArgs`. Events without a declared list
     * simply offer no placeholders rather than offering broken ones.
     */
    args?: EventArg[];
}

userMacro.typescript:
export type BuiltInMacroType = 'uppercase' | 'color' | 'replace' | 'beep' | 'mute' | 'unmute' | 'command' | 'slowBlink' | 'rapidBlink' | 'dim' | 'functionalBind' | 'wrap' | 'notify' | 'push' | 'speak' | 'echo' | 'script' | 'group';

export interface UserMacro {
    type: BuiltInMacroType | string;  // string allows plugin macros like "plugin:..."
    color?: string;  // color: the match's colour; echo: the printed line's, absent = default
    background?: string;  // color only: the match's background, absent = unchanged
    to?: string;
    command?: string;
    soundKey?: string;
    label?: string;
    message?: string;  // notify/push/speak/echo text; empty falls back to matched text for pattern triggers (not echo)
    /**
     * push only: send even if another push went out within the rate-limit
     * window. For alerts the player considers important enough that being
     * swallowed by an unrelated hp alert a moment earlier is worse than the
     * extra buzz.
     */
    bypassCooldown?: boolean;
    pluginConfig?: Record<string, any>;
    /** script: the automation script to run. */
    scriptId?: string;
    /** group: the automation group to switch. */
    groupId?: string;
    /** group: what to do with it; absent flips it. */
    groupState?: 'on' | 'off' | 'toggle';
    // Dim effect options
    dimStartOpacity?: number;
    dimEndOpacity?: number;
    dimDuration?: number;
    dimEasing?: DimEasing;
    // Wrap (prefix/suffix) options
    wrapPrefix?: string;
    wrapSuffix?: string;
    wrapScope?: 'match' | 'line';
}

bind.typescript:
export interface Bind {
    key: string;
    ctrl?: boolean;
    alt?: boolean;
    shift?: boolean;
}

export interface CustomBind extends Bind {
    command: string;
}

export interface DirectionBinds {
    n: Bind;
    s: Bind;
    w: Bind;
    e: Bind;
    nw: Bind;
    ne: Bind;
    sw: Bind;
    se: Bind;
    u: Bind;
    d: Bind;
    zerknij: Bind;
    special: Bind;
}

export interface BindSettings {
    main: Bind;
    /** Optional separate key for gates functional bind. When undefined, inherits from `main`. */
    mainGates?: Bind;
    /** Optional separate key for transport functional bind. When undefined, inherits from `main`. */
    mainTransport?: Bind;
    /** Optional separate key for loot functional bind. When undefined, inherits from `main`. */
    mainLoot?: Bind;
    lamp: Bind;
    attack: Bind;
    support: Bind;
    moveMode: Bind;
    roomBind: Bind;
    drinkable: Bind;
    /** Gate bind - knocks on the gate of the current location. */
    gateBind: Bind;
    /** Double-press bind that sends the `+k` game command. */
    doubleK: Bind;
    directions: DirectionBinds;
    /**
     * Modifier held with a direction key to walk that step in a given walk mode
     * (`przemknij`, a plugin's own walking), keyed by walk mode id. A mode with no
     * entry uses its own default; an entry with no modifier switches it off.
     */
    walkModes?: Record<string, WalkModifiers>;
    custom: CustomBind[];
    temp: Bind[];
    enemy: Bind[];
    enemyBlock: Bind[];
}

export interface Keymap {
    /** Unique keymap identifier (UUID). */
    id: string;
    /** User-facing name (e.g. "Laptop", "Numpad"). */
    name: string;
    /** The actual bindings for this keymap. */
    binds: BindSettings;
    /** ISO timestamp of creation. */
    createdAt: string;
}

export interface KeymapStore {
    /** Format version for future-proofing migration. */
    version: 1;
    /** All keymaps keyed by their ID. */
    keymaps: Record<string, Keymap>;
}

settingChange.typescript:
interface SettingChange {
    /** Klucz z katalogu ustawien: "<magazyn>.<pole>", np. "renderSettings.colorTheme". */
    key: string;
    /** Nowa wartosc — typ zgodny z polem `type` wpisu katalogu. */
    value: unknown;
}
